Pokaż kod
boarding = {
  const ROWS = 24;
  const COLS = ["A", "B", "C", "D", "E", "F"];
  const AISLE_AFTER = 2;
  const COLORS = {
    empty: "#d8dee8", seated: "#22c55e", walking: "#2563eb",
    stowing: "#f59e0b", waiting: "#ef4444", aisle: "#eef2f7",
    outline: "#7b8798", text: "#344054"
  };

  // Powtarzalny generator liczb pseudolosowych.
  function rng(seed) {
    let x = seed &gt;&gt;&gt; 0;
    return () =&gt; ((x = (1664525 * x + 1013904223) &gt;&gt;&gt; 0) / 4294967296);
  }
  function shuffled(xs, random) {
    const a = xs.slice();
    for (let i = a.length - 1; i &gt; 0; --i) {
      const j = Math.floor(random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
  function passengers() {
    return Array.from({length: ROWS}, (_, r) =&gt;
      COLS.map((seat, c) =&gt; ({id: `${r + 1}${seat}`, row:r, col:c, seat}))
    ).flat();
  }
  function orderFor(method, random) {
    const all = passengers();
    if (method === "random") return shuffled(all, random);
    if (method === "back") {
      const ans = [];
      for (let r = ROWS - 1; r &gt;= 0; --r)
        ans.push(...shuffled(all.filter(p =&gt; p.row === r), random));
      return ans;
    }
    // Metoda Steffena: najpierw okna, potem środek, na końcu przejście;
    // w każdej grupie naprzemienne rzędy od tyłu i obie strony kabiny.
    const ans = [];
    for (const pair of [[0,5],[1,4],[2,3]]) {
      for (const parity of [1,0]) {
        for (let r = ROWS - 1; r &gt;= 0; --r) {
          if (r % 2 === parity)
            for (const c of pair) ans.push(all.find(p =&gt; p.row === r && p.col === c));
        }
      }
    }
    return ans;
  }
  function makeSim(method, seed) {
    const random = rng(seed);
    return {
      method, random, queue:orderFor(method, random), active:[], seated:new Set(),
      time:0, done:false, simultaneous:0
    };
  }
  function seatDelay(p, seated) {
    // 3 jednostki na bagaż oraz dodatkowy czas, gdy trzeba przepuścić
    // osobę siedzącą bliżej przejścia.
    let delay = 3;
    if (p.col === 0) delay += (seated.has(`${p.row}-2`) ? 2 : 0) + (seated.has(`${p.row}-1`) ? 2 : 0);
    if (p.col === 1) delay += seated.has(`${p.row}-2`) ? 2 : 0;
    if (p.col === 5) delay += (seated.has(`${p.row}-3`) ? 2 : 0) + (seated.has(`${p.row}-4`) ? 2 : 0);
    if (p.col === 4) delay += seated.has(`${p.row}-3`) ? 2 : 0;
    return delay;
  }
  function step(sim) {
    if (sim.done) return;
    sim.time++;

    const blocked = new Set(sim.active.filter(p =&gt; p.state === "stowing").map(p =&gt; p.pos));
    const occupied = new Set(sim.active.filter(p =&gt; p.state !== "seated").map(p =&gt; p.pos));

    // Aktualizujemy od najdalszego pasażera, aby nikt nie przeszedł przez inną osobę.
    const moving = sim.active.slice().sort((a,b) =&gt; b.pos - a.pos);
    for (const p of moving) {
      if (p.state === "stowing") {
        p.wait--;
        if (p.wait &lt;= 0) {
          p.state = "seated";
          sim.seated.add(`${p.row}-${p.col}`);
          occupied.delete(p.pos);
        }
      } else if (p.state === "walking") {
        if (p.pos === p.row) {
          p.state = "stowing";
          p.wait = seatDelay(p, sim.seated);
        } else {
          const next = p.pos + 1;
          if (!occupied.has(next) && !blocked.has(next)) {
            occupied.delete(p.pos); p.pos = next; occupied.add(p.pos);
          }
        }
      }
    }
    sim.active = sim.active.filter(p =&gt; p.state !== "seated");

    // Jedna osoba może wejść w każdej jednostce czasu, jeśli początek przejścia jest wolny.
    if (sim.queue.length && !occupied.has(-1) && !occupied.has(0)) {
      const p = sim.queue.shift();
      sim.active.push({...p, pos:-1, state:"walking", wait:0});
    }
    sim.done = sim.queue.length === 0 && sim.active.length === 0;
  }

  const methods = [
    {id:"back", label:"Od tyłu do przodu"},
    {id:"random", label:"Kolejność losowa"},
    {id:"steffen", label:"Metoda Steffena"}
  ];
  const root = html`&lt;div&gt;
    &lt;div class="boarding-controls"&gt;
      &lt;button class="primary" data-action="start"&gt;▶ Start&lt;/button&gt;
      &lt;button data-action="pause"&gt;Ⅱ Pauza&lt;/button&gt;
      &lt;button data-action="reset"&gt;↺ Od początku&lt;/button&gt;
      &lt;label&gt;Tempo &lt;input data-speed type="range" min="1" max="10" value="5"&gt;&lt;/label&gt;
      &lt;label&gt;Ziarno &lt;input data-seed type="number" min="1" max="9999" value="2026" style="width:5.5rem"&gt;&lt;/label&gt;
    &lt;/div&gt;
    &lt;div class="boarding-grid"&gt;&lt;/div&gt;
    &lt;div class="boarding-legend"&gt;
      &lt;span class="boarding-key"&gt;&lt;i class="boarding-dot" style="background:${COLORS.walking}"&gt;&lt;/i&gt; idzie&lt;/span&gt;
      &lt;span class="boarding-key"&gt;&lt;i class="boarding-dot" style="background:${COLORS.stowing}"&gt;&lt;/i&gt; odkłada bagaż&lt;/span&gt;
      &lt;span class="boarding-key"&gt;&lt;i class="boarding-dot" style="background:${COLORS.seated}"&gt;&lt;/i&gt; siedzi&lt;/span&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;
  const grid = root.querySelector(".boarding-grid");
  const panels = new Map();
  for (const m of methods) {
    const panel = html`&lt;section class="boarding-panel"&gt;&lt;h3&gt;${m.label}&lt;/h3&gt;&lt;div class="boarding-status"&gt;&lt;/div&gt;&lt;svg viewBox="0 0 250 666" role="img" aria-label="Symulacja: ${m.label}"&gt;&lt;/svg&gt;&lt;/section&gt;`;
    grid.append(panel); panels.set(m.id, panel);
  }

  let sims, timer = null;
  function reset() {
    pause();
    const seed = +root.querySelector("[data-seed]").value || 2026;
    sims = methods.map((m,i) =&gt; makeSim(m.id, seed + 101 * i));
    render();
  }
  function start() {
    if (timer || sims.every(s =&gt; s.done)) return;
    const loop = () =&gt; {
      for (const s of sims) step(s);
      render();
      if (sims.every(s =&gt; s.done)) pause();
    };
    const speed = +root.querySelector("[data-speed]").value;
    timer = setInterval(loop, 310 - 27 * speed);
  }
  function pause() { if (timer) clearInterval(timer); timer = null; }

  function render() {
    for (const sim of sims) {
      const panel = panels.get(sim.method), svg = panel.querySelector("svg");
      const y = r =&gt; 625 - r * 24;
      let marks = `&lt;rect x="64" y="32" width="122" height="630" rx="55" fill="none" stroke="${COLORS.outline}" stroke-width="2"/&gt;`;
      marks += `&lt;rect x="116" y="42" width="18" height="590" fill="${COLORS.aisle}"/&gt;`;
      for (let r=0; r&lt;ROWS; ++r) {
        marks += `&lt;text x="51" y="${y(r)+5}" text-anchor="end" font-size="9" fill="${COLORS.text}"&gt;${r+1}&lt;/text&gt;`;
        for (let c=0; c&lt;6; ++c) {
          const x = 70 + c*16 + (c&gt;AISLE_AFTER ? 18 : 0);
          const fill = sim.seated.has(`${r}-${c}`) ? COLORS.seated : COLORS.empty;
          marks += `&lt;rect x="${x}" y="${y(r)-8}" width="12" height="16" rx="2" fill="${fill}"/&gt;`;
        }
      }
      for (const p of sim.active) {
        const cy = p.pos &lt; 0 ? 646 : y(p.pos);
        const fill = p.state === "stowing" ? COLORS.stowing : COLORS.walking;
        marks += `&lt;circle cx="125" cy="${cy}" r="6" fill="${fill}" stroke="white" stroke-width="1"&gt;&lt;title&gt;${p.id}&lt;/title&gt;&lt;/circle&gt;`;
      }
      svg.innerHTML = marks;
      const seated = sim.seated.size;
      panel.querySelector(".boarding-status").textContent = sim.done
        ? `Koniec: ${sim.time} jednostek czasu`
        : `czas ${sim.time} · siedzi ${seated}/144`;
    }
  }
  root.querySelector("[data-action=start]").onclick = start;
  root.querySelector("[data-action=pause]").onclick = pause;
  root.querySelector("[data-action=reset]").onclick = reset;
  root.querySelector("[data-speed]").onchange = () =&gt; { const wasRunning = !!timer; pause(); if (wasRunning) start(); };
  root.querySelector("[data-seed]").onchange = reset;
  invalidation.then(pause);
  reset();
  return root;
}
