2.3 Deska Galtona
Ostatni przykład to deska Galtona zaprezentowana poniżej. Kule spadają po kołkach za każdym razem odbijając się losowo w lewo bądź prawo. Poniżej widzimy histogram (znormalizowany wykres słupkowy) liczby kul, które opuściły deskę przez dane miejsce.


Pokaż kod
galton = {
  const N = 12;
  const W = 720;
  const H = 650;

  const top = 55;
  const rowGap = 35;
  const pegGap = 38;
  const center = W / 2;

  const binTop = top + N * rowGap + 25;
  const binHeight = 125;

  const root = html`&lt;div class="galton-root"&gt;
    &lt;style&gt;
      .galton-root {
        max-width: 760px;
        margin: 0 auto;
      }

      .galton-controls {
        display: flex;
        align-items: end;
        gap: 1rem;
        flex-wrap: wrap;
        margin: 0.5rem 0 1rem;
      }

      .galton-control {
        display: grid;
        gap: 0.25rem;
        min-width: 210px;
        flex: 1;
      }

      .galton-control label {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
      }

      .galton-buttons {
        display: flex;
        gap: 0.5rem;
      }

      .galton-buttons button {
        padding: 0.4rem 0.75rem;
        border: 1px solid #98a2b3;
        border-radius: 0.4rem;
        background: var(--bs-body-bg, #fff);
        color: var(--bs-body-color, #222);
        cursor: pointer;
      }

      .galton-buttons button[data-play] {
        background: #2563eb;
        border-color: #2563eb;
        color: white;
      }

      .galton-root svg {
        width: 100%;
        height: auto;
        display: block;
      }

      .galton-status {
        text-align: center;
        color: #667085;
        font-variant-numeric: tabular-nums;
        margin-top: 0.35rem;
      }
    &lt;/style&gt;

    &lt;div class="galton-controls"&gt;
      &lt;div class="galton-control"&gt;
        &lt;label&gt;
          &lt;span&gt;Prawdopodobieństwo ruchu w prawo&lt;/span&gt;
          &lt;output data-pout&gt;0,50&lt;/output&gt;
        &lt;/label&gt;

        &lt;input
          data-prob
          type="range"
          min="0.05"
          max="0.95"
          value="0.50"
          step="0.01"
        &gt;
      &lt;/div&gt;

      &lt;div class="galton-control"&gt;
        &lt;label&gt;
          &lt;span&gt;Prędkość&lt;/span&gt;
          &lt;output data-sout&gt;5&lt;/output&gt;
        &lt;/label&gt;

        &lt;input
          data-speed
          type="range"
          min="1"
          max="10"
          value="5"
          step="1"
        &gt;
      &lt;/div&gt;

      &lt;div class="galton-buttons"&gt;
        &lt;button data-play&gt;▶ Start&lt;/button&gt;
        &lt;button data-reset&gt;↺ Od początku&lt;/button&gt;
      &lt;/div&gt;
    &lt;/div&gt;

    &lt;svg
      viewBox="0 0 ${W} ${H}"
      role="img"
      aria-label="Animowana deska Galtona"&gt;
    &lt;/svg&gt;

    &lt;div class="galton-status" aria-live="polite"&gt;&lt;/div&gt;
  &lt;/div&gt;`;

  const svg = root.querySelector("svg");
  const status = root.querySelector(".galton-status");

  const probInput = root.querySelector("[data-prob]");
  const speedInput = root.querySelector("[data-speed]");

  const pOutput = root.querySelector("[data-pout]");
  const speedOutput = root.querySelector("[data-sout]");

  const playButton = root.querySelector("[data-play]");
  const resetButton = root.querySelector("[data-reset]");

  let counts = Array(N + 1).fill(0);
  let balls = [];
  let total = 0;

  let running = false;
  let animationFrame = null;
  let lastSpawn = 0;
  let nextId = 0;

  const pegX = (row, column) =&gt;
    center + (column - row / 2) * pegGap;

  const pegY = row =&gt;
    top + row * rowGap;

  const binX = k =&gt;
    center + (k - N / 2) * pegGap;

  function createBall(now) {
    const p = Number(probInput.value);

    const choices = Array.from(
      {length: N},
      () =&gt; Math.random() &lt; p ? 1 : 0
    );

    const columns = [0];

    for (const choice of choices) {
      columns.push(columns.at(-1) + choice);
    }

    balls.push({
      id: nextId++,
      born: now,
      columns,
      result: columns.at(-1)
    });
  }

  function ballPosition(ball, now) {
    const speed = Number(speedInput.value);
    const stepDuration = 330 - 25 * speed;

    const age = (now - ball.born) / stepDuration;
    const segment = Math.floor(age);
    const u = age - segment;

    if (segment &gt;= N) {
      return {
        done: true,
        x: binX(ball.result),
        y: binTop
      };
    }

    const x0 = pegX(
      segment,
      ball.columns[segment]
    );

    const y0 = pegY(segment) - 11;

    const x1 = pegX(
      segment + 1,
      ball.columns[segment + 1]
    );

    const y1 = pegY(segment + 1) - 11;

    // Wygładzenie ruchu poziomego
    const smooth = u * u * (3 - 2 * u);

    // Niewielkie odbicie między kołkami
    const arc = -9 * Math.sin(Math.PI * u);

    return {
      done: false,
      x: x0 + (x1 - x0) * smooth,
      y: y0 + (y1 - y0) * u + arc
    };
  }

  function binomialProbability(k, p) {
    let binomialCoefficient = 1;

    for (let j = 1; j &lt;= k; ++j) {
      binomialCoefficient *= (N - j + 1) / j;
    }

    return (
      binomialCoefficient *
      p ** k *
      (1 - p) ** (N - k)
    );
  }

  function draw(now = performance.now()) {
    const p = Number(probInput.value);
    const maxCount = Math.max(8, ...counts);
    const baseY = binTop + binHeight;

    let marks = `
      &lt;rect
        x="0"
        y="0"
        width="${W}"
        height="${H}"
        fill="transparent"
      /&gt;
    `;

    // Kołki deski Galtona
    for (let row = 0; row &lt;= N; ++row) {
      for (let column = 0; column &lt;= row; ++column) {
        marks += `
          &lt;circle
            cx="${pegX(row, column)}"
            cy="${pegY(row)}"
            r="4.2"
            fill="#344054"
          /&gt;
        `;
      }
    }

    // Histogram
    for (let k = 0; k &lt;= N; ++k) {
      const x = binX(k);

      const barHeight =
        binHeight * counts[k] / maxCount;

      const expectedHeight =
        binHeight *
        binomialProbability(k, p) *
        Math.max(total, 1) /
        maxCount;

      marks += `
        &lt;rect
          x="${x - pegGap * 0.43}"
          y="${baseY - barHeight}"
          width="${pegGap * 0.86}"
          height="${barHeight}"
          rx="2"
          fill="#2563eb"
          opacity="0.78"
        /&gt;
      `;

      // Teoretyczna liczba kulek w pojemniku
      marks += `
        &lt;line
          x1="${x - pegGap * 0.43}"
          y1="${baseY - expectedHeight}"
          x2="${x + pegGap * 0.43}"
          y2="${baseY - expectedHeight}"
          stroke="#ef4444"
          stroke-width="2"
        /&gt;
      `;

      marks += `
        &lt;text
          x="${x}"
          y="${baseY + 19}"
          text-anchor="middle"
          font-size="12"
          fill="#475467"&gt;
          ${k}
        &lt;/text&gt;
      `;

      if (counts[k] &gt; 0) {
        marks += `
          &lt;text
            x="${x}"
            y="${baseY - barHeight - 5}"
            text-anchor="middle"
            font-size="11"
            fill="#344054"&gt;
            ${counts[k]}
          &lt;/text&gt;
        `;
      }
    }

    marks += `
      &lt;line
        x1="${binX(0) - pegGap / 2}"
        y1="${baseY}"
        x2="${binX(N) + pegGap / 2}"
        y2="${baseY}"
        stroke="#667085"
      /&gt;
    `;

    // Spadające kulki
    for (const ball of balls) {
      const position = ballPosition(ball, now);

      marks += `
        &lt;circle
          cx="${position.x}"
          cy="${position.y}"
          r="7"
          fill="#f59e0b"
          stroke="#92400e"
          stroke-width="1.2"
        /&gt;
      `;
    }

    // Legenda
    marks += `
      &lt;g transform="translate(18, ${H - 21})"&gt;
        &lt;line
          x1="0"
          y1="0"
          x2="20"
          y2="0"
          stroke="#ef4444"
          stroke-width="2"
        /&gt;

        &lt;text
          x="27"
          y="4"
          font-size="12"
          fill="#475467"&gt;
          wartość oczekiwana z rozkładu dwumianowego
        &lt;/text&gt;
      &lt;/g&gt;
    `;

    svg.innerHTML = marks;

    const empiricalMean = total
      ? counts.reduce(
          (sum, count, k) =&gt; sum + k * count,
          0
        ) / total
      : null;

    status.textContent =
      `Liczba kulek: ${total}` +
      ` · średnia empiryczna: ${
        empiricalMean === null
          ? "—"
          : empiricalMean.toFixed(2)
      }` +
      ` · średnia teoretyczna: ${(N * p).toFixed(2)}`;
  }

  function frame(now) {
    if (!running) {
      return;
    }

    const speed = Number(speedInput.value);
    const spawnDelay = 620 - 48 * speed;

    if (now - lastSpawn &gt;= spawnDelay) {
      createBall(now);
      lastSpawn = now;
    }

    const remainingBalls = [];

    for (const ball of balls) {
      if (ballPosition(ball, now).done) {
        counts[ball.result] += 1;
        total += 1;
      } else {
        remainingBalls.push(ball);
      }
    }

    balls = remainingBalls;

    draw(now);

    animationFrame =
      requestAnimationFrame(frame);
  }

  function setRunning(value) {
    running = value;

    playButton.textContent =
      running ? "Ⅱ Pauza" : "▶ Start";

    if (running) {
      lastSpawn = performance.now() - 1000;

      animationFrame =
        requestAnimationFrame(frame);
    } else if (animationFrame) {
      cancelAnimationFrame(animationFrame);
      animationFrame = null;
    }
  }

  playButton.onclick = () =&gt; {
    setRunning(!running);
  };

  resetButton.onclick = () =&gt; {
    setRunning(false);

    counts = Array(N + 1).fill(0);
    balls = [];
    total = 0;

    draw();
  };

  probInput.oninput = () =&gt; {
    pOutput.value = Number(probInput.value)
      .toFixed(2)
      .replace(".", ",");

    draw();
  };

  speedInput.oninput = () =&gt; {
    speedOutput.value = speedInput.value;
  };

  invalidation.then(() =&gt; {
    setRunning(false);
  });

  draw();

  return root;
}











